  console.log(`ADS server listening on port ${config.port}`);
});

// Graceful shutdown
process.on('SIGTERM', async () => {
  console.log('Shutting down...');
  server.close();
  await pool.end();
  redis.disconnect();
  process.exit(0);
});

module.exports = { app, pool, redis, cache };
